function sortedPairSumExists(nums, target) {
  let l = 0;
  let r = nums.length - 1;
  while (l < r) {
    const sum = nums[l] + nums[r];
    if (sum === target) return true;
    if (sum < target) l += 1;
    else r -= 1;
  }
  return false;
}

function isPalindrome(s) {
  const t = s.toLowerCase().replace(/[^a-z0-9]/g, "");
  let l = 0;
  let r = t.length - 1;
  while (l < r) {
    if (t[l] !== t[r]) return false;
    l += 1;
    r -= 1;
  }
  return true;
}

function twoSumII(numbers, target) {
  let l = 0;
  let r = numbers.length - 1;
  while (l < r) {
    const sum = numbers[l] + numbers[r];
    if (sum === target) return [l + 1, r + 1];
    if (sum < target) l += 1;
    else r -= 1;
  }
  return [];
}

function threeSum(nums) {
  const sorted = nums.slice().sort((a, b) => a - b);
  const out = [];
  for (let i = 0; i < sorted.length - 2; i += 1) {
    if (i > 0 && sorted[i] === sorted[i - 1]) continue;
    let l = i + 1;
    let r = sorted.length - 1;
    while (l < r) {
      const sum = sorted[i] + sorted[l] + sorted[r];
      if (sum === 0) {
        out.push([sorted[i], sorted[l], sorted[r]]);
        l += 1;
        r -= 1;
        while (l < r && sorted[l] === sorted[l - 1]) l += 1;
        while (l < r && sorted[r] === sorted[r + 1]) r -= 1;
      } else if (sum < 0) l += 1;
      else r -= 1;
    }
  }
  return out;
}

function maxArea(height) {
  let l = 0;
  let r = height.length - 1;
  let best = 0;
  while (l < r) {
    best = Math.max(best, Math.min(height[l], height[r]) * (r - l));
    if (height[l] < height[r]) l += 1;
    else r -= 1;
  }
  return best;
}

function trap(height) {
  let l = 0;
  let r = height.length - 1;
  let leftMax = 0;
  let rightMax = 0;
  let water = 0;
  while (l < r) {
    if (height[l] < height[r]) {
      if (height[l] >= leftMax) leftMax = height[l];
      else water += leftMax - height[l];
      l += 1;
    } else {
      if (height[r] >= rightMax) rightMax = height[r];
      else water += rightMax - height[r];
      r -= 1;
    }
  }
  return water;
}
